package disaster.util; import java.util.*; public final class Json{private Json(){}public static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";}public static String resourceMap(Map<String,long[]> m){StringBuilder b=new StringBuilder("{");for(var e:m.entrySet()){if(b.length()>1)b.append(',');long[]v=e.getValue();b.append(quote(e.getKey())).append(":{\"required\":").append(v[0]).append(",\"available\":").append(v[1]).append(",\"allocated\":").append(v[2]).append(",\"shortage\":").append(v[3]).append('}');}return b.append('}').toString();} public static String mapToJson(Map<String,Object> m) { StringBuilder b=new StringBuilder("{"); for(var e:m.entrySet()){if(b.length()>1)b.append(','); b.append(quote(e.getKey())).append(":"); Object v=e.getValue(); if(v instanceof String) b.append(quote((String)v)); else b.append(v); } return b.append('}').toString(); }}
